}

static int count_entries(const char *dir, const char *suffix)
{
	DIR *d = opendir(dir);
	struct dirent *e;
	int n = 0;

	if (d == NULL)
		return -1;
	while ((e = readdir(d)) != NULL) {
		size_t len = strlen(e->d_name), m = strlen(suffix);

		if (len >= m && strcmp(e->d_name + len - m, suffix) == 0)
			n++;
	}
	closedir(d);
	return n;
}

static void test_pir_to_storage(void)
{
	char root[256], data[300], run[300], fake[512], path[600];
	struct seen s = { 0 };
	uint64_t first_id;

	t_mkdtemp(root);
	snprintf(data, sizeof data, "%s/data", root);
	snprintf(run, sizeof run, "%s/run", root);
	snprintf(fake, sizeof fake, "%s/fake-rpicam-still.sh", getenv("PSS_TEST_DIR"));
	CHECK(chmod(fake, 0755) == 0);
	setenv("PSS_DATA_DIR", data, 1);
	setenv("PSS_RUN_DIR", run, 1);
	setenv("PSS_RPICAM", fake, 1);

	/* Session 1: camera works. */
	unsetenv("FAKE_RPICAM_FAIL");
	run_session(data, &s);
	first_id = s.last.event_id;
	CHECK(s.boots == 1 && s.max_boot == 1);
	CHECK(s.last.kind == PSS_EV_MOTION_ONLY);
	CHECK(s.last.n_images == 3);
	CHECK(!(s.last.flags & PSS_EVF_NO_IMAGES));
	CHECK(s.last.flags & PSS_EVF_AUDIO_OFFLINE); /* no micd running */
	CHECK(s.last.pir_edges == 1);
	CHECK(s.last.end_mono_ns >= s.last.start_mono_ns);
	snprintf(path, sizeof path, "%s/clips/%" PRIu64 ".dir", data, first_id);
	CHECK(count_entries(path, ".jpg") == 3);
	snprintf(path, sizeof path, "%s/stats", data);
	CHECK(count_entries(path, ".pel") >= 1);	/* stats log lives apart from events */
	snprintf(path, sizeof path, "%s/events", data);
	CHECK(count_entries(path, ".pel") == 1);

	/* Session 2: same data dir, camera fails. Ids continue, boot count grows. */
	setenv("FAKE_RPICAM_FAIL", "1", 1);
	run_session(data, &s);
	CHECK(s.boots == 2 && s.max_boot == 2);
	CHECK(s.last.event_id == first_id + 1);
	CHECK(s.last.flags & PSS_EVF_NO_IMAGES);
	CHECK(s.last.n_images == 0);

	snprintf(path, sizeof path, "%s/clips", data);
	CHECK(count_entries(path, ".tmp") == 0);
	unsetenv("FAKE_RPICAM_FAIL");
	t_rm_rf(root);
}

int main(void)
{
	if (getenv("PSS_BIN_DIR") == NULL || getenv("PSS_TEST_DIR") == NULL) {
		fprintf(stderr, "run via `make test` (needs PSS_BIN_DIR and PSS_TEST_DIR)\n");
		return 2;
	}
	T_RUN(test_pir_to_storage);
	T_END();
}
/*
 * micd: USB microphone capture + feature extraction (DESIGN.md Section 2, Section 4).
 *
 * Two threads joined by an SPSC ring: the capture thread blocks in
 * snd_pcm_readi() and pushes 20 ms chunks; the main thread wakes on an
 * eventfd, computes features every 882-sample hop over a 1024-sample window,
 * and sends MIC_FRAME messages to the hub. The ring holds ~11.9 s of audio,
 * the size the 10 s pre-roll clip will need (M4).
 *
 * M3 status: written and unit-tested (features) off-device; NOT yet run on
 * the Blue Snowball, which has not arrived.
 *
 * Exit codes: 0 on SIGTERM/SIGINT, 1 on error, 2 on usage, 3 when the
 * device disappears (unplugged), per DESIGN.md Section 6.
 */
#include "capture/mic/features.h"
#include "common/client.h"
#include "common/log.h"
#include "common/time.h"
#include "common/util.h"

#include <alsa/asoundlib.h>
#include <errno.h>
#include <getopt.h>
#include <inttypes.h>
#include <poll.h>
#include <pthread.h>
#include <signal.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/eventfd.h>
#include <sys/signalfd.h>
#include <unistd.h>

#define EXIT_USAGE 2
#define EXIT_DEVICE_GONE 3
#define RATE 44100
#define LATENCY_US 200000
#define RING_SIZE (1u << 19)	/* samples; ~11.9 s at 44.1 kHz */
#define RING_MASK (RING_SIZE - 1)
#define HB_PERIOD_NS (5 * PSS_NS_PER_S)

struct micd {
	snd_pcm_t *pcm;
	int16_t *ring;
	_Atomic uint64_t head;	/* written by capture thread */
	_Atomic uint64_t tail;	/* written by main thread */
	int wake_fd;
	atomic_int stop;
	atomic_int fatal;	/* exit code requested by the capture thread */
	atomic_ulong xruns;
	atomic_ulong overflow;	/* samples dropped because the ring was full */
};

static void usage(void)
{
	fprintf(stderr, "usage: micd [--device=default]\n");
}

static void ring_push(struct micd *m, const int16_t *src, uint64_t n)
{
	uint64_t head = atomic_load_explicit(&m->head, memory_order_relaxed);
	uint64_t tail = atomic_load_explicit(&m->tail, memory_order_acquire);
	uint64_t space = RING_SIZE - (head - tail);

	if (n > space) {
		atomic_fetch_add(&m->overflow, (unsigned long)(n - space));
		n = space;
	}
	for (uint64_t i = 0; i < n; i++)
		m->ring[(head + i) & RING_MASK] = src[i];
	atomic_store_explicit(&m->head, head + n, memory_order_release);
}

static uint64_t ring_avail(struct micd *m)
{
	return atomic_load_explicit(&m->head, memory_order_acquire) -
	       atomic_load_explicit(&m->tail, memory_order_relaxed);
#ifndef PSS_STORE_EVLOG_H
#define PSS_STORE_EVLOG_H

/*
 * Mechanism D, event and stats logs (DESIGN.md Section 5): two append-only
 * logs of segment files, events/seg-NNNNNN.pel and stats/seg-NNNNNN.pel,
 * each record framed as
 *     [len u32][type u16][ver u16][payload: len bytes][crc32 u32]
 * with the CRC over header + payload. Native little-endian (Pi 5 and the lab
 * machines are both LE). Recovery at open truncates the newest segment of
 * each log at the first record with a bad length or CRC, and closes any
 * ENTRY that was opened but never closed as interrupted (power lost).
 */

#include <stdint.h>

#define PSS_SEG_MAX (4u * 1024 * 1024)
#define PSS_REC_MAX_PAYLOAD 4096u
#define PSS_REC_HDR 8u
#define PSS_REC_TRAILER 4u
#define PSS_REC_VER 1
#define PSS_STATS_RETAIN_S (7 * 24 * 3600)	/* whole stats segments older than this are deleted */
#define PSS_STATS_ROLL_NS (24 * 3600 * INT64_C(1000000000)) /* so a segment can age out */

enum pss_log_which {
	PSS_LOG_EVENTS = 0,
	PSS_LOG_STATS = 1,
};

enum pss_rec_type {
	PSS_REC_BOOT = 1,	/* events log */
	PSS_REC_EVENT = 2,	/* events log: a complete event, or the close of an EVENT_OPEN */
	PSS_REC_STATS = 3,	/* stats log only */
	PSS_REC_EVENT_OPEN = 4,	/* events log: ENTRY confirmed, made durable at once */
};

enum pss_event_kind {
	PSS_EV_MOTION_ONLY = 1,
	PSS_EV_ENTRY = 2,	/* needs fusion (M4) */
	PSS_EV_SOUND_ONLY = 3,	/* needs fusion (M4) */
};

enum pss_event_flag {
	PSS_EVF_NO_IMAGES = 1u << 0,
	PSS_EVF_AUDIO_OFFLINE = 1u << 1,
	PSS_EVF_CLOSED_AT_SHUTDOWN = 1u << 2,
	PSS_EVF_INTERRUPTED = 1u << 3,	/* opened, power lost before close; end unknown */
};

/* Payload structs have no implicit padding; read them back with memcpy (payloads are unaligned). */
struct pss_rec_boot {
	uint64_t boot_no;
	int64_t mono_ns;
	int64_t wall_ns;
};

/* Images, if any, live in clips/<event_id>.dir. */
struct pss_rec_event {
	uint64_t event_id;
	int64_t start_mono_ns;
	int64_t end_mono_ns;
	int64_t start_wall_ns;
	uint32_t kind;
	uint32_t flags;
	uint32_t pir_edges;
	uint32_t n_images;
};

struct pss_rec_event_open {
	uint64_t event_id;
	int64_t start_mono_ns;
	int64_t start_wall_ns;
	uint32_t kind;
	uint32_t flags;
};

struct pss_rec_stats {
	int64_t mono_ns;
	int64_t wall_ns;
	uint64_t pir_edges;

content.content:
/*
 * hub: the single writer (DESIGN.md Section 2). Accepts sensor daemons on
 * $PSS_RUN_DIR/hub.sock, turns PIR edges into events, asks camd for an image
 * burst per event, and commits everything through the store (mechanism D).
 *
 * M3 scope: no fusion yet (needs the mic and collected data, M4), so every
 * event is MOTION_ONLY and every successful burst is kept. Mic frames are
 * accepted and counted when micd is present.
 *
 * Exit codes: 0 on SIGTERM/SIGINT, 1 on error (including any store write
 * failure, so the supervisor restarts us and recovery runs), 2 on usage.
 */
#include "common/ipc.h"
#include "common/log.h"
#include "common/time.h"
#include "common/util.h"
#include "store/clip.h"
#include "store/evlog.h"

#include <errno.h>
#include <getopt.h>
#include <inttypes.h>
#include <signal.h>
#include <stdio.h>
#include <string.h>
#include <sys/epoll.h>
#include <sys/signalfd.h>
#include <sys/socket.h>
#include <sys/stat.h>
#include <unistd.h>

#define EXIT_USAGE 2
#define MAX_CONNS 8
#define HB_FIRST_NS (5 * PSS_NS_PER_S)
#define HB_EVERY_NS (60 * PSS_NS_PER_S)
#define HB_STALE_NS (15 * PSS_NS_PER_S)
#define BURST_SLACK_NS (20 * PSS_NS_PER_S)
#define BURST_EST_BYTES (9ull * 1024 * 1024)	/* upper end of DESIGN.md Section 5's 6-9 MB */

enum { TAG_LISTEN = MAX_CONNS, TAG_SIG, TAG_TICK };

struct conn {
	int fd;
	uint32_t role;		/* PSS_ROLE_NONE until HELLO */
	int64_t last_hb_ns;
};

enum burst_state { BURST_NONE, BURST_PENDING, BURST_DONE };

struct event {
	int open;
	uint64_t id;
	int64_t start_mono_ns;
	int64_t start_wall_ns;
	int64_t last_activity_ns;
	int pir_high;
	uint32_t pir_edges;
	uint32_t flags;
	uint32_t n_images;
	enum burst_state burst;
	int64_t burst_deadline_ns;
};

struct hub {
	struct pss_store store;
	int store_open;
	int listen_fd, epoll_fd, sig_fd, tick_fd;
	struct conn conns[MAX_CONNS];
	struct event ev;
	int64_t start_ns, next_hb_ns;
	uint64_t pir_edges, mic_frames, cam_bursts, cam_failures, events_closed;
	/* config */
	int64_t quiet_ns;
	uint32_t burst_frames, burst_interval_ms, floor_pct;
	uint64_t quota_bytes;
	char sock_path[108];
};

static struct hub hub;

static void usage(void)
{
	fprintf(stderr, "usage: hub [--quiet-ms=30000] [--burst-frames=20] [--burst-interval-ms=500]\n"
			"           [--quota-mb=2048] [--floor-pct=5]\n");
}

static struct conn *conn_for_role(struct hub *h, uint32_t role)
{
	for (int i = 0; i < MAX_CONNS; i++)
		if (h->conns[i].fd >= 0 && h->conns[i].role == role)
			return &h->conns[i];
	return NULL;
}

static int role_alive(struct hub *h, uint32_t role, int64_t now)
{
	struct conn *c = conn_for_role(h, role);

	return c != NULL && now - c->last_hb_ns < HB_STALE_NS;
}

static void trigger_burst(struct hub *h, int64_t now)
{
	struct event *ev = &h->ev;
	struct conn *cam = conn_for_role(h, PSS_ROLE_CAM);
	struct pss_msg m;
	uint32_t evicted = 0;
	int q;

	if (cam == NULL) {
		pss_log("event %" PRIu64 ": camd not connected, no images", ev->id);
		ev->flags |= PSS_EVF_NO_IMAGES;
		return;
	}
	q = clip_enforce_quota(h->store.clips_dir_fd, h->quota_bytes, BURST_EST_BYTES, h->floor_pct, &evicted);
	if (q != 0) {
		pss_log("event %" PRIu64 ": %s, no images", ev->id, q > 0 ? "clips disabled" : "quota check failed");
		ev->flags |= PSS_EVF_NO_IMAGES;
		return;
	}
	pss_msg_init(&m, PSS_MSG_CAM_TRIGGER);
	m.u.cam_trigger.event_id = ev->id;
	m.u.cam_trigger.frames = h->burst_frames;
	m.u.cam_trigger.interval_ms = h->burst_interval_ms;
	if (ipc_send(cam->fd, &m) != 0) {
		pss_log("event %" PRIu64 ": trigger to camd failed: %s", ev->id, strerror(errno));
		ev->flags |= PSS_EVF_NO_IMAGES;
		return;
	}
	ev->burst = BURST_PENDING;
	ev->burst_deadline_ns = now + (int64_t)h->burst_frames * h->burst_interval_ms * PSS_NS_PER_MS + BURST_SLACK_NS;
	h->cam_bursts++;
}

static void open_event(struct hub *h, int64_t ts, int64_t now)
{
	struct event *ev = &h->ev;

	memset(ev, 0, sizeof *ev);
	ev->open = 1;
	ev->id = h->store.next_event_id++;
	ev->start_mono_ns = ts;
	ev->start_wall_ns = pss_wall_ns() - (now - ts);
	ev->last_activity_ns = now;
	ev->pir_high = 1;
	ev->pir_edges = 1;
	if (!role_alive(h, PSS_ROLE_MIC, now))
		ev->flags |= PSS_EVF_AUDIO_OFFLINE;
	pss_log("event %" PRIu64 " opened (PIR rise)", ev->id);
	trigger_burst(h, now);
}

/* Writes the event record and makes it durable. 0, or -1 on a store failure. */
static int close_event(struct hub *h, int64_t end_ns, uint32_t extra_flags)
{
	struct event *ev = &h->ev;
	struct pss_rec_event r;

	memset(&r, 0, sizeof r);
	r.event_id = ev->id;
	r.start_mono_ns = ev->start_mono_ns;
	r.end_mono_ns = end_ns;
	r.start_wall_ns = ev->start_wall_ns;
	r.kind = PSS_EV_MOTION_ONLY;
	r.flags = ev->flags | extra_flags;
	r.pir_edges = ev->pir_edges;
	r.n_images = ev->n_images;
	if (store_event_close(&h->store, &r) != 0) {
		pss_log("event %" PRIu64 ": store write failed; exiting so recovery runs", ev->id);
		return -1;
	}
	pss_log("event %" PRIu64 " closed: MOTION_ONLY dur=%.1fs edges=%" PRIu32 " images=%" PRIu32 "%s%s",
		ev->id, (double)(end_ns - ev->start_mono_ns) / PSS_NS_PER_S, r.pir_edges, r.n_images,
		(r.flags & PSS_EVF_NO_IMAGES) ? " no-images" : "",
		(r.flags & PSS_EVF_AUDIO_OFFLINE) ? " audio-offline" : "");
	h->events_closed++;
	ev->open = 0;
	return 0;
}

static void on_cam_done(struct hub *h, const struct pss_msg *m)
{
	struct event *ev = &h->ev;
	uint64_t id = m->u.cam_done.event_id;
	uint32_t n = 0;

	if (!ev->open || id != ev->id || ev->burst != BURST_PENDING) {
		pss_log("camd: late result for event %" PRIu64 ", discarding", id);
		clip_discard(h->store.clips_dir_fd, id);
		return;
	}
	ev->burst = BURST_DONE;
	if (m->u.cam_done.status != 0 || m->u.cam_done.frames == 0) {
		h->cam_failures++;
		ev->flags |= PSS_EVF_NO_IMAGES;
		pss_log("event %" PRIu64 ": burst failed (status %" PRId32 ", %" PRIu32 " frames)",
			id, m->u.cam_done.status, m->u.cam_done.frames);
		clip_discard(h->store.clips_dir_fd, id);
		return;
	}
	if (clip_commit(h->store.clips_dir_fd, id, &n) != 0) {
		h->cam_failures++;
		ev->flags |= PSS_EVF_NO_IMAGES;
		clip_discard(h->store.clips_dir_fd, id);
		return;
	}
	ev->n_images = n;
	pss_log("event %" PRIu64 ": committed %" PRIu32 " images to clips/%" PRIu64 ".dir", id, n, id);
}

static void on_pir_edge(struct hub *h, const struct pss_msg *m, int64_t now)
{
	struct event *ev = &h->ev;

	h->pir_edges++;
	if (m->u.pir.rising) {
		if (!ev->open) {
			open_event(h, m->mono_ns, now);
			return;
		}
		ev->pir_edges++;
		ev->pir_high = 1;
		ev->last_activity_ns = now;
	} else if (ev->open) {
		ev->pir_high = 0;
		ev->last_activity_ns = now;
	}
}

static void conn_drop(struct hub *h, int idx, const char *why)
{
	struct conn *c = &h->conns[idx];

	if (epoll_ctl(h->epoll_fd, EPOLL_CTL_DEL, c->fd, NULL) != 0)
		pss_log("epoll_ctl DEL: %s", strerror(errno));
	if (close(c->fd) != 0)
		pss_log("close conn: %s", strerror(errno));
	pss_log("%s disconnected (%s)", pss_role_name(c->role), why);
	if (c->role == PSS_ROLE_CAM && h->ev.open && h->ev.burst == BURST_PENDING) {
		h->ev.burst = BURST_DONE;
		h->ev.flags |= PSS_EVF_NO_IMAGES;
		h->cam_failures++;
	}
	if (c->role == PSS_ROLE_PIR)
		h->ev.pir_high = 0; /* don't hold an event open on a dead sensor */
	c->fd = -1;
	c->role = PSS_ROLE_NONE;
}

static void handle_msg(struct hub *h, int idx, const struct pss_msg *m, int64_t now)
{
	struct conn *c = &h->conns[idx];

	if (c->role == PSS_ROLE_NONE && m->type != PSS_MSG_HELLO) {
		conn_drop(h, idx, "message before HELLO");
		return;
	}
	switch (m->type) {
	case PSS_MSG_HELLO:
		if (m->u.hello.role < PSS_ROLE_PIR || m->u.hello.role > PSS_ROLE_MIC) {
			conn_drop(h, idx, "bad role");
			return;
		}
		c->role = m->u.hello.role;
		c->last_hb_ns = now;
		pss_log("%s connected (pid %" PRIu32 ")", pss_role_name(c->role), m->u.hello.pid);
		break;
	case PSS_MSG_HEARTBEAT:
		c->last_hb_ns = now;
		break;
	case PSS_MSG_PIR_EDGE:
		on_pir_edge(h, m, now);
		break;
	case PSS_MSG_CAM_DONE:
		on_cam_done(h, m);
		break;
	case PSS_MSG_MIC_FRAME:
		h->mic_frames++;
		break;
	default:
		pss_log("%s: unknown message type %u", pss_role_name(c->role), m->type);
		break;
	}
}

static void conn_readable(struct hub *h, int idx, int64_t now)
{
	struct pss_msg m;
	int r;

	while (h->conns[idx].fd >= 0) {
		r = ipc_recv(h->conns[idx].fd, &m);
		if (r == 1) {
			handle_msg(h, idx, &m, now);
			continue;
		}
		if (r == 0)
			conn_drop(h, idx, "EOF");
		else if (errno != EAGAIN)
			conn_drop(h, idx, strerror(errno));
		return;
	}
}

static void accept_all(struct hub *h, int64_t now)
{
	for (;;) {
		struct epoll_event ee = { .events = EPOLLIN };
		int fd = accept4(h->listen_fd, NULL, NULL, SOCK_CLOEXEC | SOCK_NONBLOCK);
		int idx = -1;

		if (fd < 0) {
			if (errno != EAGAIN && errno != EINTR)
				pss_log("accept4: %s", strerror(errno));
			return;
		}
		for (int i = 0; i < MAX_CONNS; i++) {
			if (h->conns[i].fd < 0) {
				idx = i;
				break;
			}
		}
		if (idx < 0) {
			pss_log("too many connections, refusing one");
			close(fd);
			continue;
		}
		ee.data.u32 = (uint32_t)idx;
		if (epoll_ctl(h->epoll_fd, EPOLL_CTL_ADD, fd, &ee) != 0) {
			pss_log("epoll_ctl ADD: %s", strerror(errno));
			close(fd);
			continue;
		}
		h->conns[idx] = (struct conn){ .fd = fd, .role = PSS_ROLE_NONE, .last_hb_ns = now };
	}
}

static const char *alive_str(struct hub *h, uint32_t role, int64_t now)
{
	if (role_alive(h, role, now))
		return "ok";
	return conn_for_role(h, role) ? "STALE" : "absent";
}

/* Stats record (1/min) doubles as the soak heartbeat line. 0 or -1. */
static int write_stats(struct hub *h, int64_t now)
{
	struct pss_rec_stats r;

	memset(&r, 0, sizeof r);
	r.mono_ns = now;
	r.wall_ns = pss_wall_ns();
	r.pir_edges = h->pir_edges;
	r.mic_frames = h->mic_frames;
	r.cam_bursts = h->cam_bursts;
	r.cam_failures = h->cam_failures;
	for (uint32_t role = PSS_ROLE_PIR; role <= PSS_ROLE_MIC; role++)
		if (role_alive(h, role, now))
			r.sensors_ok |= 1u << role;
	if (store_append(&h->store, PSS_LOG_STATS, PSS_REC_STATS, &r, sizeof r) != 0 ||
	    store_sync(&h->store, PSS_LOG_STATS) != 0)
		return -1;
	pss_log("hb: up=%" PRId64 "s pird=%s camd=%s micd=%s edges=%" PRIu64 " events=%" PRIu64
		" bursts=%" PRIu64 " cam_fail=%" PRIu64 " mic_frames=%" PRIu64,
		(now - h->start_ns) / PSS_NS_PER_S, alive_str(h, PSS_ROLE_PIR, now),
		alive_str(h, PSS_ROLE_CAM, now), alive_str(h, PSS_ROLE_MIC, now),
		h->pir_edges, h->events_closed, h->cam_bursts, h->cam_failures, h->mic_frames);
	return 0;
}

static int tick(struct hub *h, int64_t now)
{
	struct event *ev = &h->ev;

	if (ev->open && ev->burst == BURST_PENDING && now > ev->burst_deadline_ns) {
		pss_log("event %" PRIu64 ": camd result overdue, no images", ev->id);
		ev->burst = BURST_DONE;
		ev->flags |= PSS_EVF_NO_IMAGES;
		h->cam_failures++;
	}
	if (ev->open && !ev->pir_high && ev->burst != BURST_PENDING &&
	    now - ev->last_activity_ns >= h->quiet_ns && close_event(h, ev->last_activity_ns, 0) != 0)
		return -1;
	if (now >= h->next_hb_ns) {
		if (write_stats(h, now) != 0)
			return -1;
		h->next_hb_ns = now + HB_EVERY_NS;
	}
	return 0;
}

static int write_boot(struct hub *h)
{
	struct pss_rec_boot b;

	memset(&b, 0, sizeof b);
	b.boot_no = h->store.boot_no + 1;
	b.mono_ns = pss_mono_ns();
	b.wall_ns = pss_wall_ns();
	if (store_append(&h->store, PSS_LOG_EVENTS, PSS_REC_BOOT, &b, sizeof b) != 0 ||
	    store_sync(&h->store, PSS_LOG_EVENTS) != 0)
		return -1;
	h->store.boot_no = b.boot_no;
	pss_log("boot #%" PRIu64 " recorded; next event id %" PRIu64, b.boot_no, h->store.next_event_id);
	return 0;
}

static int epoll_add(struct hub *h, int fd, uint32_t tag)
{
	struct epoll_event ee = { .events = EPOLLIN, .data.u32 = tag };

	if (epoll_ctl(h->epoll_fd, EPOLL_CTL_ADD, fd, &ee) != 0) {
		pss_log("epoll_ctl ADD: %s", strerror(errno));
		return -1;
	}
	return 0;
}

static int parse_args(struct hub *h, int argc, char **argv)
{
	static const struct option opts[] = {
		{ "quiet-ms", required_argument, NULL, 'q' },
		{ "burst-frames", required_argument, NULL, 'f' },
		{ "burst-interval-ms", required_argument, NULL, 'i' },
		{ "quota-mb", required_argument, NULL, 'Q' },
		{ "floor-pct", required_argument, NULL, 'F' },
		{ "help", no_argument, NULL, 'h' },
		{ NULL, 0, NULL, 0 },
	};
	uint32_t quiet_ms = 30000, quota_mb = 2048, v;
	int opt;

	h->burst_frames = 20;
	h->burst_interval_ms = 500;
	h->floor_pct = 5;
	while ((opt = getopt_long(argc, argv, "", opts, NULL)) != -1) {
		if (opt != 'h' && opt != '?' && pss_parse_u32(optarg, 0, UINT32_MAX, &v) != 0)
			opt = '?';
		switch (opt) {
		case 'q': quiet_ms = v; break;
		case 'f': if (v < 1 || v > 1000) return -1; h->burst_frames = v; break;
		case 'i': if (v < 1 || v > 10000) return -1; h->burst_interval_ms = v; break;
		case 'Q': quota_mb = v; break;
		case 'F': if (v > 100) return -1; h->floor_pct = v; break;
		default: return -1;
		}
	}
	h->quiet_ns = (int64_t)quiet_ms * PSS_NS_PER_MS;
	h->quota_bytes = (uint64_t)quota_mb * 1024 * 1024;
	return 0;
}

int main(int argc, char **argv)
{
	const int sigs[] = { SIGINT, SIGTERM };
	struct hub *h = &hub;
	int code = 1;

	pss_log_init("hub");
	h->listen_fd = h->epoll_fd = h->sig_fd = h->tick_fd = -1;
	for (int i = 0; i < MAX_CONNS; i++)
		h->conns[i].fd = -1;
	if (parse_args(h, argc, argv) != 0) {
		usage();
		return EXIT_USAGE;
	}

	h->sig_fd = pss_signalfd(sigs, 2);
	if (h->sig_fd < 0)
		goto out;
	if (mkdir(pss_run_dir(), 0755) != 0 && errno != EEXIST) {
		pss_log("mkdir %s: %s", pss_run_dir(), strerror(errno));
		goto out;
	}
	if (store_open(&h->store, pss_data_dir()) != 0)
		goto out;
	h->store_open = 1;
	if (write_boot(h) != 0)
		goto out;
	if (ipc_sock_path(h->sock_path, sizeof h->sock_path) != 0)
		goto out;
	h->listen_fd = ipc_listen(h->sock_path);
	if (h->listen_fd < 0)
		goto out;
	h->tick_fd = pss_timerfd(PSS_NS_PER_S, PSS_NS_PER_S);
	if (h->tick_fd < 0)
		goto out;
	h->epoll_fd = epoll_create1(EPOLL_CLOEXEC);
	if (h->epoll_fd < 0) {
		pss_log("epoll_create1: %s", strerror(errno));
		goto out;
	}
	if (epoll_add(h, h->listen_fd, TAG_LISTEN) != 0 || epoll_add(h, h->sig_fd, TAG_SIG) != 0 ||
	    epoll_add(h, h->tick_fd, TAG_TICK) != 0)
		goto out;

	h->start_ns = pss_mono_ns();
	h->next_hb_ns = h->start_ns + HB_FIRST_NS;
	pss_log("start pid=%d data=%s sock=%s quiet=%" PRId64 "ms burst=%" PRIu32 "x%" PRIu32 "ms",
		(int)getpid(), pss_data_dir(), h->sock_path, h->quiet_ns / PSS_NS_PER_MS,
		h->burst_frames, h->burst_interval_ms);

	for (;;) {
		struct epoll_event evs[16];
		int n = epoll_wait(h->epoll_fd, evs, 16, -1);
		int64_t now;

		if (n < 0) {
			if (errno == EINTR)
				continue;
			pss_log("epoll_wait: %s", strerror(errno));
			goto out;
		}
		now = pss_mono_ns();
		for (int i = 0; i < n; i++) {
			uint32_t tag = evs[i].data.u32;

			if (tag == TAG_SIG) {
				struct signalfd_siginfo si;

				if (read(h->sig_fd, &si, sizeof si) != (ssize_t)sizeof si)
					pss_log("signalfd read: %s", strerror(errno));
				else
					pss_log("signal %u, shutting down", si.ssi_signo);
				if (h->ev.open) {
					if (h->ev.burst == BURST_PENDING)
						h->ev.flags |= PSS_EVF_NO_IMAGES;
					if (close_event(h, now, PSS_EVF_CLOSED_AT_SHUTDOWN) != 0)
						goto out;
				}
				code = 0;
				goto out;
			} else if (tag == TAG_LISTEN) {
				accept_all(h, now);
			} else if (tag == TAG_TICK) {
				if (pss_timerfd_drain(h->tick_fd) != 0 || tick(h, now) != 0)
					goto out;
			} else if (tag < MAX_CONNS) {
				conn_readable(h, (int)tag, now);
			}
		}
	}
out:
	for (int i = 0; i < MAX_CONNS; i++)
		if (h->conns[i].fd >= 0)
			close(h->conns[i].fd);
	if (h->epoll_fd >= 0)
		close(h->epoll_fd);
	if (h->listen_fd >= 0) {
		close(h->listen_fd);
		if (unlink(h->sock_path) != 0)
			pss_log("unlink %s: %s", h->sock_path, strerror(errno));
	}
	if (h->tick_fd >= 0)
		close(h->tick_fd);
	if (h->sig_fd >= 0)
		close(h->sig_fd);
	if (h->store_open)
		store_close(&h->store);
	pss_log("exit %d", code);
	return code;
}
#ifndef PSS_COMMON_IPC_H
#define PSS_COMMON_IPC_H

/*
 * Daemon <-> hub messages over AF_UNIX SOCK_SEQPACKET (DESIGN.md Section 2): one
 * fixed-size struct per packet, so boundaries are preserved and a dead peer
 * shows up as EOF/EPIPE. All processes run on the same Pi, so the struct is
 * sent in native layout.
 */

#include <stddef.h>
#include <stdint.h>

#define PSS_IPC_VER 1
#define PSS_NBANDS 8

enum pss_role {
	PSS_ROLE_NONE = 0,
	PSS_ROLE_PIR = 1,
	PSS_ROLE_CAM = 2,
	PSS_ROLE_MIC = 3,
};

enum pss_msg_type {
	PSS_MSG_HELLO = 1,	/* daemon -> hub, first message */
	PSS_MSG_HEARTBEAT,	/* daemon -> hub, every 5 s */
	PSS_MSG_PIR_EDGE,	/* pird -> hub */
	PSS_MSG_CAM_TRIGGER,	/* hub -> camd */
	PSS_MSG_CAM_DONE,	/* camd -> hub */
	PSS_MSG_MIC_FRAME,	/* micd -> hub, 50 Hz */
};

struct pss_msg {
	uint16_t type;
	uint16_t ver;
	uint32_t seq;
	int64_t mono_ns;	/* CLOCK_MONOTONIC; for PIR edges, the kernel's edge timestamp */
	union {
		struct { uint32_t role; uint32_t pid; } hello;
		struct { uint64_t dropped; uint64_t count; } hb;
		struct { uint32_t rising; uint32_t pad; } pir;
		struct { uint64_t event_id; uint32_t frames; uint32_t interval_ms; } cam_trigger;
		/* status: 0 ok, >0 rpicam exit code (128+sig if killed), <0 -errno in camd */
		struct { uint64_t event_id; int32_t status; uint32_t frames; } cam_done;
		struct { float rms; float flux; float band[PSS_NBANDS]; } mic;
	} u;
};

const char *pss_role_name(uint32_t role);

/* Zeroes *m (no uninitialised padding on the wire), sets type and mono_ns = now. */
void pss_msg_init(struct pss_msg *m, uint16_t type);

/* "$PSS_RUN_DIR/hub.sock". Returns 0 or -1 (path too long). */
int ipc_sock_path(char *buf, size_t n);

/* Nonblocking listening socket at path (stale socket file removed). fd or -1, logged. */
int ipc_listen(const char *path);
/* Nonblocking connected socket. fd or -1 with errno set; not logged (callers retry). */
int ipc_connect(const char *path);

/* 0 or -1 with errno. */
int ipc_send(int fd, struct pss_msg *m);
/* 1 = message, 0 = peer closed, -1 = error with errno (EAGAIN, EBADMSG size, EPROTO version). */
int ipc_recv(int fd, struct pss_msg *m);

#endif

#ifndef PSS_CAPTURE_FEATURES_H
#define PSS_CAPTURE_FEATURES_H

/*
 * Per-frame audio features (DESIGN.md Section 4): 1024-point Hann window every
 * 20 ms (882 samples at 44.1 kHz); RMS, log energy in 8 log-spaced bands
 * from 100 Hz to 8 kHz, and spectral flux (sum of positive band increases).
 * Our own radix-2 FFT; no libraries.
 */

#include "common/ipc.h"

#include <stdint.h>

#define PSS_FFT_N 1024
#define PSS_HOP 882
#define PSS_FEAT_LO_HZ 100.0
#define PSS_FEAT_HI_HZ 8000.0

struct pss_features {
	float rms;		/* of the raw frame, full scale = 1.0 */
	float flux;		/* 0 on the first frame */
	float band[PSS_NBANDS];	/* log10 energy */
};

struct feat_state {
	float window[PSS_FFT_N];
	float cos_t[PSS_FFT_N / 2];
	float sin_t[PSS_FFT_N / 2];
	uint16_t band_lo[PSS_NBANDS];	/* FFT bins [lo, hi) */
	uint16_t band_hi[PSS_NBANDS];
	float prev[PSS_NBANDS];
	int have_prev;
};

/* Returns 0, or -1 if rate is too low for the 8 kHz top band. */
int feat_init(struct feat_state *s, unsigned rate);
void feat_compute(struct feat_state *s, const int16_t frame[PSS_FFT_N], struct pss_features *out);

#endif
/*
 * End-to-end on the lab machine: real hub + real camd (with the
 * fake-rpicam-still.sh stand-in for the camera), and this test playing the
 * part of pird by sending PIR edge messages over the hub socket. The live
 * demo uses the real pird and rpicam-still on the Pi; this checks the
 * pipeline and storage around them.
 */
#include "t.h"

#include "common/ipc.h"
#include "common/time.h"
#include "store/evlog.h"

#include <dirent.h>
#include <errno.h>
#include <inttypes.h>
#include <signal.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <time.h>
#include <unistd.h>

struct seen {
	int boots, events;
	uint64_t max_boot;
	struct pss_rec_event last;
};

static int seen_visitor(uint32_t seg, uint16_t type, uint16_t ver, const void *p, uint32_t len, void *arg)
{
	struct seen *s = arg;

	(void)seg;
	(void)ver;
	if (type == PSS_REC_EVENT && len == sizeof s->last) {
		memcpy(&s->last, p, sizeof s->last);
		s->events++;
	} else if (type == PSS_REC_BOOT && len == sizeof(struct pss_rec_boot)) {
		struct pss_rec_boot b;

		memcpy(&b, p, sizeof b);
		if (b.boot_no > s->max_boot)
			s->max_boot = b.boot_no;
		s->boots++;
	}
	return 0;
}

static void sleep_ms(long ms)
{
	struct timespec ts = { ms / 1000, (ms % 1000) * 1000000L };

	while (nanosleep(&ts, &ts) != 0 && errno == EINTR)
		;
}

static pid_t spawn(char *const argv[])
{
	pid_t pid = fork();

	if (pid == 0) {
		execv(argv[0], argv);
		perror(argv[0]);
		_exit(127);
	}
	return pid;
}

/* SIGTERM, then wait up to 5 s; returns the exit status or -1. */
static int stop(pid_t pid)
{
	int st;

	if (pid <= 0)
		return -1;
	kill(pid, SIGTERM);
	for (int i = 0; i < 500; i++) {
		pid_t r = waitpid(pid, &st, WNOHANG);

		if (r == pid)
			return WIFEXITED(st) ? WEXITSTATUS(st) : -1;
		sleep_ms(10);
	}
	kill(pid, SIGKILL);
	waitpid(pid, &st, 0);
	return -1;
}

static int connect_retry(const char *path)
{
	for (int i = 0; i < 500; i++) {
		int fd = ipc_connect(path);

		if (fd >= 0)
			return fd;
		sleep_ms(10);
	}
	return -1;
}

static void send_edge(int fd, int rising)
{
	struct pss_msg m;

	pss_msg_init(&m, PSS_MSG_PIR_EDGE);
	m.u.pir.rising = (uint32_t)rising;
	CHECK(ipc_send(fd, &m) == 0);
}

/* One hub+camd lifetime with one PIR-triggered event. Fills *out from disk. */
static void run_session(const char *data, struct seen *out)
{
	char hub[512], camd[512], sock[300];
	const char *bindir = getenv("PSS_BIN_DIR");
	struct pss_msg m;
	struct seen before = { 0 };
	pid_t hp, cp;
	int fd;

	snprintf(hub, sizeof hub, "%s/hub", bindir);
	snprintf(camd, sizeof camd, "%s/camd", bindir);
	if (access(data, F_OK) == 0)
		CHECK(store_scan(data, PSS_LOG_EVENTS, seen_visitor, &before) == 0);

	hp = spawn((char *[]){ hub, "--quiet-ms=300", "--burst-frames=3", "--burst-interval-ms=20", NULL });
	CHECK(hp > 0);
	CHECK(ipc_sock_path(sock, sizeof sock) == 0);
	fd = connect_retry(sock);
	CHECK(fd >= 0);
	cp = spawn((char *[]){ camd, NULL });
	CHECK(cp > 0);

	/* Act as pird. */
	pss_msg_init(&m, PSS_MSG_HELLO);
	m.u.hello.role = PSS_ROLE_PIR;
	m.u.hello.pid = (uint32_t)getpid();
	CHECK(ipc_send(fd, &m) == 0);
	sleep_ms(1000); /* let camd connect */
	send_edge(fd, 1);
	sleep_ms(50);
	send_edge(fd, 0);

	/* Event closes after the burst returns and 300 ms of quiet (1 s tick). */
	for (int i = 0; i < 100; i++) {
		memset(out, 0, sizeof *out);
		CHECK(store_scan(data, PSS_LOG_EVENTS, seen_visitor, out) == 0);
		if (out->events > before.events)
			break;
		sleep_ms(100);
	}
	CHECK(out->events == before.events + 1);
	CHECK(stop(cp) == 0);
	CHECK(stop(hp) == 0);
	close(fd);
}

static int count_entries(const char *dir, const char *suffix)
{
	DIR *d = opendir(dir);
	struct dirent *e;
	int n = 0;

	if (d == NULL)
		return -1;
	while ((e = readdir(d)) != NULL) {
		size_t len = strlen(e->d_name), m = strlen(suffix);

		if (len >= m && strcmp(e->d_name + len - m, suffix) == 0)
			n++;
	}
	closedir(d);
	return n;
}

static void test_pir_to_storage(void)
{
	char root[256], data[300], run[300], fake[512], path[600];
	struct seen s = { 0 };
	uint64_t first_id;

	t_mkdtemp(root);
	snprintf(data, sizeof data, "%s/data", root);
	snprintf(run, sizeof run, "%s/run", root);
	snprintf(fake, sizeof fake, "%s/fake-rpicam-still.sh", getenv("PSS_TEST_DIR"));
	CHECK(chmod(fake, 0755) == 0);
	setenv("PSS_DATA_DIR", data, 1);
	setenv("PSS_RUN_DIR", run, 1);
	setenv("PSS_RPICAM", fake, 1);

	/* Session 1: camera works. */
	unsetenv("FAKE_RPICAM_FAIL");
	run_session(data, &s);
	first_id = s.last.event_id;
	CHECK(s.boots == 1 && s.max_boot == 1);
	CHECK(s.last.kind == PSS_EV_MOTION_ONLY);
	CHECK(s.last.n_images == 3);
	CHECK(!(s.last.flags & PSS_EVF_NO_IMAGES));
	CHECK(s.last.flags & PSS_EVF_AUDIO_OFFLINE); /* no micd running */
	CHECK(s.last.pir_edges == 1);
	CHECK(s.last.end_mono_ns >= s.last.start_mono_ns);
	snprintf(path, sizeof path, "%s/clips/%" PRIu64 ".dir", data, first_id);
	CHECK(count_entries(path, ".jpg") == 3);
	snprintf(path, sizeof path, "%s/stats", data);
	CHECK(count_entries(path, ".pel") >= 1);	/* stats log lives apart from events */
	snprintf(path, sizeof path, "%s/events", data);
	CHECK(count_entries(path, ".pel") == 1);

	/* Session 2: same data dir, camera fails. Ids continue, boot count grows. */
	setenv("FAKE_RPICAM_FAIL", "1", 1);
	run_session(data, &s);
	CHECK(s.boots == 2 && s.max_boot == 2);
	CHECK(s.last.event_id == first_id + 1);
	CHECK(s.last.flags & PSS_EVF_NO_IMAGES);
	CHECK(s.last.n_images == 0);

	snprintf(path, sizeof path, "%s/clips", data);
	CHECK(count_entries(path, ".tmp") == 0);
	unsetenv("FAKE_RPICAM_FAIL");
	t_rm_rf(root);
}

int main(void)
{
	if (getenv("PSS_BIN_DIR") == NULL || getenv("PSS_TEST_DIR") == NULL) {
		fprintf(stderr, "run via `make test` (needs PSS_BIN_DIR and PSS_TEST_DIR)\n");
		return 2;
	}
	T_RUN(test_pir_to_storage);
	T_END();
}
/*
 * micd: USB microphone capture + feature extraction (DESIGN.md Section 2, Section 4).
 *
 * Two threads joined by an SPSC ring: the capture thread blocks in
 * snd_pcm_readi() and pushes 20 ms chunks; the main thread wakes on an
 * eventfd, computes features every 882-sample hop over a 1024-sample window,
 * and sends MIC_FRAME messages to the hub. The ring holds ~11.9 s of audio,
 * the size the 10 s pre-roll clip will need (M4).
 *
 * M3 status: written and unit-tested (features) off-device; NOT yet run on
 * the Blue Snowball, which has not arrived.
 *
 * Exit codes: 0 on SIGTERM/SIGINT, 1 on error, 2 on usage, 3 when the
 * device disappears (unplugged), per DESIGN.md Section 6.
 */
#include "capture/mic/features.h"
#include "common/client.h"
#include "common/log.h"
#include "common/time.h"
#include "common/util.h"

#include <alsa/asoundlib.h>
#include <errno.h>
#include <getopt.h>
#include <inttypes.h>
#include <poll.h>
#include <pthread.h>
#include <signal.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/eventfd.h>
#include <sys/signalfd.h>
#include <unistd.h>

#define EXIT_USAGE 2
#define EXIT_DEVICE_GONE 3
#define RATE 44100
#define LATENCY_US 200000
#define RING_SIZE (1u << 19)	/* samples; ~11.9 s at 44.1 kHz */
#define RING_MASK (RING_SIZE - 1)
#define HB_PERIOD_NS (5 * PSS_NS_PER_S)

struct micd {
	snd_pcm_t *pcm;
	int16_t *ring;
	_Atomic uint64_t head;	/* written by capture thread */
	_Atomic uint64_t tail;	/* written by main thread */
	int wake_fd;
	atomic_int stop;
	atomic_int fatal;	/* exit code requested by the capture thread */
	atomic_ulong xruns;
	atomic_ulong overflow;	/* samples dropped because the ring was full */
};

static void usage(void)
{
	fprintf(stderr, "usage: micd [--device=default]\n");
}

static void ring_push(struct micd *m, const int16_t *src, uint64_t n)
{
	uint64_t head = atomic_load_explicit(&m->head, memory_order_relaxed);
	uint64_t tail = atomic_load_explicit(&m->tail, memory_order_acquire);
	uint64_t space = RING_SIZE - (head - tail);

	if (n > space) {
		atomic_fetch_add(&m->overflow, (unsigned long)(n - space));
		n = space;
	}
	for (uint64_t i = 0; i < n; i++)
		m->ring[(head + i) & RING_MASK] = src[i];
	atomic_store_explicit(&m->head, head + n, memory_order_release);
}

static uint64_t ring_avail(struct micd *m)
{
	return atomic_load_explicit(&m->head, memory_order_acquire) -
	       atomic_load_explicit(&m->tail, memory_order_relaxed);
#ifndef PSS_STORE_EVLOG_H
#define PSS_STORE_EVLOG_H

/*
 * Mechanism D, event and stats logs (DESIGN.md Section 5): two append-only
 * logs of segment files, events/seg-NNNNNN.pel and stats/seg-NNNNNN.pel,
 * each record framed as
 *     [len u32][type u16][ver u16][payload: len bytes][crc32 u32]
 * with the CRC over header + payload. Native little-endian (Pi 5 and the lab
 * machines are both LE). Recovery at open truncates the newest segment of
 * each log at the first record with a bad length or CRC, and closes any
 * ENTRY that was opened but never closed as interrupted (power lost).
 */

#include <stdint.h>

#define PSS_SEG_MAX (4u * 1024 * 1024)
#define PSS_REC_MAX_PAYLOAD 4096u
#define PSS_REC_HDR 8u
#define PSS_REC_TRAILER 4u
#define PSS_REC_VER 1
#define PSS_STATS_RETAIN_S (7 * 24 * 3600)	/* whole stats segments older than this are deleted */
#define PSS_STATS_ROLL_NS (24 * 3600 * INT64_C(1000000000)) /* so a segment can age out */

enum pss_log_which {
	PSS_LOG_EVENTS = 0,
	PSS_LOG_STATS = 1,
};

enum pss_rec_type {
	PSS_REC_BOOT = 1,	/* events log */
	PSS_REC_EVENT = 2,	/* events log: a complete event, or the close of an EVENT_OPEN */
	PSS_REC_STATS = 3,	/* stats log only */
	PSS_REC_EVENT_OPEN = 4,	/* events log: ENTRY confirmed, made durable at once */
};

enum pss_event_kind {
	PSS_EV_MOTION_ONLY = 1,
	PSS_EV_ENTRY = 2,	/* needs fusion (M4) */
	PSS_EV_SOUND_ONLY = 3,	/* needs fusion (M4) */
};

enum pss_event_flag {
